// ─── File: src/main/java/com/bank/update/service/AccountUpdateService.java ───
package com.bank.update.service;

import com.bank.update.model.Account;
import jakarta.persistence.EntityManager;
import jakarta.persistence.PersistenceContext;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Slf4j
public class AccountUpdateService {

    @PersistenceContext
    private EntityManager em;

    // (Avoid) BROKEN: builds a half-empty Account and merges it.
    // name/balance are null → merge copies nulls → blanks the stored values.
    @Transactional
    public void updatePhoneBroken(String id, String newPhone) {
        Account partial = new Account(id);
        partial.setPhone(newPhone);   // holderName, balance = null
        em.merge(partial);            // DANGER: null-overwrite of name & balance
        log.warn("Merged a partial entity — name and balance may be wiped!");
    }

    // (Recommended) CORRECT: load the managed entity, change only the field, let dirty checking flush.
    // With @DynamicUpdate, the SQL is: update accounts set phone=? where id=?
    @Transactional
    public void updatePhone(String id, String newPhone) {
        Account acct = em.find(Account.class, id);  // managed, full state loaded
        acct.setPhone(newPhone);                     // only phone changes
        // no save needed — dirty checking + @DynamicUpdate → single-column UPDATE
        log.info("Phone updated for {}; only the phone column will be written", id);
    }
}
```
